int a[100], n;
void input() { cin >> n; for (int i = 0; i < n; i++) cin >> a[i]; }
void mySort() { sort(a, a + n); }
void output() { for (int i = 0; i < n; i++) cout << a[i] << " "; cout << endl; }
int main() { input(); mySort(); output(); return 0; }

